/**
 * jszip.min.js (Lightweight PK Zip Builder for Extension Content Scripts)
 * Standalone PKZip archive constructor supporting asynchronous blob/uint8array file additions.
 */
(function (global) {
  'use strict';

  function CRC32() {
    let table = new Int32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let k = 0; k < 8; k++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      }
      table[i] = c;
    }
    return function (buf, crc) {
      crc = (crc || 0) ^ (-1);
      for (let i = 0; i < buf.length; i++) {
        crc = (crc >>> 8) ^ table[(crc ^ buf[i]) & 0xFF];
      }
      return (crc ^ (-1)) >>> 0;
    };
  }

  const crc32 = CRC32();

  class MinimalZip {
    constructor() {
      this.files = [];
    }

    file(filename, content) {
      this.files.push({
        name: filename,
        content: content
      });
      return this;
    }

    async generateAsync(options = { type: 'blob' }) {
      const entries = [];
      let offset = 0;

      for (const f of this.files) {
        let u8;
        if (typeof f.content === 'string') {
          u8 = new TextEncoder().encode(f.content);
        } else if (f.content instanceof Uint8Array) {
          u8 = f.content;
        } else if (f.content instanceof ArrayBuffer) {
          u8 = new Uint8Array(f.content);
        } else if (f.content instanceof Blob) {
          const ab = await f.content.arrayBuffer();
          u8 = new Uint8Array(ab);
        } else {
          u8 = new TextEncoder().encode(String(f.content));
        }

        const fileNameBytes = new TextEncoder().encode(f.name);
        const crc = crc32(u8);
        const size = u8.length;

        // Local Header
        const header = new Uint8Array(30 + fileNameBytes.length);
        const view = new DataView(header.buffer);

        view.setUint32(0, 0x04034b50, true); // Local header signature
        view.setUint16(4, 10, true);         // Version needed
        view.setUint16(6, 0, true);          // General purpose flag
        view.setUint16(8, 0, true);          // Compression method (0 = store)
        view.setUint16(10, 0, true);         // Mod time
        view.setUint16(12, 0, true);         // Mod date
        view.setUint32(14, crc, true);       // CRC-32
        view.setUint32(18, size, true);      // Compressed size
        view.setUint32(22, size, true);      // Uncompressed size
        view.setUint16(26, fileNameBytes.length, true); // File name length
        view.setUint16(28, 0, true);         // Extra field length

        header.set(fileNameBytes, 30);

        entries.push({
          header,
          data: u8,
          nameBytes: fileNameBytes,
          crc,
          size,
          offset
        });

        offset += header.length + u8.length;
      }

      // Central Directory Records
      const cdParts = [];
      let cdSize = 0;

      for (const entry of entries) {
        const cdHeader = new Uint8Array(46 + entry.nameBytes.length);
        const view = new DataView(cdHeader.buffer);

        view.setUint32(0, 0x02014b50, true); // Central directory signature
        view.setUint16(4, 20, true);         // Version made by
        view.setUint16(6, 10, true);         // Version needed
        view.setUint16(8, 0, true);          // General purpose
        view.setUint16(10, 0, true);         // Compression method
        view.setUint16(12, 0, true);         // Mod time
        view.setUint16(14, 0, true);         // Mod date
        view.setUint32(16, entry.crc, true); // CRC-32
        view.setUint32(20, entry.size, true);// Compressed size
        view.setUint32(24, entry.size, true);// Uncompressed size
        view.setUint16(28, entry.nameBytes.length, true); // Name length
        view.setUint16(30, 0, true);         // Extra length
        view.setUint16(32, 0, true);         // Comment length
        view.setUint16(34, 0, true);         // Disk start
        view.setUint16(36, 0, true);         // Internal attributes
        view.setUint32(38, 0, true);         // External attributes
        view.setUint32(42, entry.offset, true); // Relative offset of local header

        cdHeader.set(entry.nameBytes, 46);
        cdParts.push(cdHeader);
        cdSize += cdHeader.length;
      }

      // End of Central Directory Record
      const eocd = new Uint8Array(22);
      const eocdView = new DataView(eocd.buffer);

      eocdView.setUint32(0, 0x06054b50, true); // EOCD signature
      eocdView.setUint16(4, 0, true);          // Disk number
      eocdView.setUint16(6, 0, true);          // CD disk
      eocdView.setUint16(8, entries.length, true);  // Entries on disk
      eocdView.setUint16(10, entries.length, true); // Total entries
      eocdView.setUint32(12, cdSize, true);    // CD size
      eocdView.setUint32(16, offset, true);    // Offset of CD
      eocdView.setUint16(20, 0, true);         // Comment length

      // Assemble all binary parts
      const totalParts = [];
      for (const entry of entries) {
        totalParts.push(entry.header);
        totalParts.push(entry.data);
      }
      for (const cdPart of cdParts) {
        totalParts.push(cdPart);
      }
      totalParts.push(eocd);

      const blob = new Blob(totalParts, { type: 'application/zip' });
      if (options.type === 'blob') {
        return blob;
      }
      return blob.arrayBuffer();
    }
  }

  // Expose as JSZip constructor compatibility
  function JSZipWrapper() {
    return new MinimalZip();
  }

  global.JSZip = JSZipWrapper;

})(typeof window !== 'undefined' ? window : this);
